/*
  Load CSS browser reset - should be first
*/
*, ::after, ::before, ::backdrop, ::file-selector-button {margin:0; padding:0; border:0 solid; box-sizing:border-box; font:inherit; vertical-align:baseline;}
h1,h2,h3,h4,h5,h6 {font-size:inherit; font-weight:inherit;}
article, aside, details, figcaption, figure, footer, header, hgroup, menu, nav, section {display:block;}
button {background:transparent; border:none;}
body {line-height:1;}
blockquote, q {quotes:none;}
table {borser-collpase:collapse; border-spacing:0;}
blockquote:before, blockquote:after, q:before, q:after {content:''; content:none;}
ol, ul {list-style:none;}

